   172|    relativePath,
   173|    line: 0,
   174|    snippet: `${loc} lines of code`,
   175|    why: `File is ${loc} LOC (≥ ${loc >= OVERSIZED_HIGH_LOC ? OVERSIZED_HIGH_LOC : OVERSIZED_WARN_LOC}) — large modules are harder to reason about and safely change.`,
